
DROP TABLE IF EXISTS ms_sample_results, ms_samples, ms_components, ms_additives, ms_eaf_step_params, ms_eaf_steps, ms_equipment_counters, meltshop_heats CASCADE;
CREATE TABLE meltshop_heats (heat_id text PRIMARY KEY, furnace_no int NOT NULL, steel_grade text NOT NULL,
  crew_id text, tap_start_utc timestamptz NOT NULL, tap_end_utc timestamptz NOT NULL,
  duration_min numeric(8,1), power_on_min numeric(8,1), electricity_mwh numeric(10,1),
  scrap_t numeric(8,1), dri_t numeric(8,1), scrap_dri_ratio numeric(6,3),
  tap_temp_c numeric(10,3), oxygen_nm3 numeric(10,0), heat_weight_t numeric(8,1),
  ladle_id text, lf_station text, lf_start_utc timestamptz, lf_end_utc timestamptz, liquidus_c numeric(8,1));
CREATE TABLE ms_components (component_id int PRIMARY KEY, chemical_name text NOT NULL);
CREATE TABLE ms_samples (sample_id text PRIMARY KEY, heat_id text REFERENCES meltshop_heats(heat_id),
  sample_time_utc timestamptz NOT NULL, station text NOT NULL);
CREATE TABLE ms_sample_results (sample_id text REFERENCES ms_samples(sample_id),
  component_id int REFERENCES ms_components(component_id), result_pct numeric(10,5), PRIMARY KEY(sample_id,component_id));
CREATE TABLE ms_additives (heat_id text REFERENCES meltshop_heats(heat_id), additive_name text, quantity_kg numeric(10,1), added_at_utc timestamptz);
CREATE TABLE ms_eaf_steps (step_id text PRIMARY KEY, heat_id text REFERENCES meltshop_heats(heat_id), step_no int, step_code text, start_utc timestamptz, end_utc timestamptz);
CREATE TABLE ms_eaf_step_params (step_id text REFERENCES ms_eaf_steps(step_id), param_name text, param_value numeric(14,2));
CREATE TABLE ms_equipment_counters (equipment_id text, equipment_type text, counter_value int, event text, event_utc timestamptz);

